const comparisonCSS = `.ui-dialog::backdrop{opacity:1;transition:opacity 160ms ease-out}.ui-dialog[data-closing=true]::backdrop{opacity:0}@starting-style{.ui-dialog[open]::backdrop{opacity:0}}.demo[data-comparison=true] .ui-demo--drawer .ui-dialog[open],:host-context(.demo[data-comparison=true]) .ui-demo--drawer .ui-dialog[open]{position:relative;inset:auto;margin:0;width:100%;height:auto;max-width:none;max-height:none;display:block;box-shadow:0 2px 8px #17243a16}`;
const legacyDialogComparisonCSS = `.demo[data-comparison=true] .site-delete .sc-confirm[open]{position:relative;inset:auto;margin:0;width:100%;height:auto;max-width:none;max-height:none;display:block}`;
// iOS Safari enlarges the visual viewport when a keyboard input renders below 16px.
// Keep this last in the generated CSS: legacy studies and Frame have smaller, more specific font rules.
const inputFocusCSS = `.demo :is(input:not([type=checkbox]):not([type=radio]):not([type=file]):not([type=range]):not([type=hidden]),textarea,select,[contenteditable]:not([contenteditable=false])){font-size:var(--input-font-size)!important}`;
const legacyResponsiveCSS = (styleId,component) => {
  const root=`.demo[data-style=${styleId}]`;
  if(component==='chart')return `@container(max-width:699px){${root} .site-chart .sc-dashboard{grid-template-columns:minmax(0,1fr)}${root} .site-chart .sc-chart-main{min-width:0;padding:14px 12px}${root} .site-chart .sc-head{display:grid;grid-template-columns:minmax(0,1fr);align-items:start;gap:10px}${root} .site-chart .sc-head h3{max-width:max-content;white-space:nowrap;font-size:clamp(20px,6vw,24px)}${root} .site-chart .sc-segment{display:flex;flex-wrap:nowrap;justify-self:start;width:max-content;max-width:100%}${root} .site-chart .sc-segment button{flex:none;white-space:nowrap;padding-inline:10px}${root} .site-chart .sc-stat{display:block;min-width:0}${root} .site-chart .sc-stat strong{font-size:clamp(22px,7vw,30px);letter-spacing:-.04em;white-space:nowrap}${root} .site-chart .sc-context{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;min-width:0;padding:14px;border-left:0;border-top:1px solid var(--line)}${root} .site-chart .sc-context h4{grid-column:1/-1;margin:0}${root} .site-chart .sc-context-metric,${root} .site-chart .sc-context-detail{min-width:0;margin:0;padding:0;border:0}${root} .site-chart .sc-context-metric strong{font-size:clamp(18px,5.5vw,22px);white-space:nowrap}${root} .site-chart .sc-tooltip{overflow-wrap:anywhere}}`;
  if(component==='table')return `@container(max-width:520px){${root} .site-orders .sc-filterbar{grid-template-columns:repeat(2,minmax(0,1fr));width:100%}${root} .site-orders .sc-search{grid-column:1/-1;min-width:0;width:100%}${root} .site-orders .sc-filterbar>label:not(.sc-search){display:block;min-width:0;width:100%}${root} .site-orders .sc-filterbar .field{display:block;width:100%;min-width:0;max-width:100%;box-sizing:border-box}}`;
  return '';
};

export const styleCSS = (styleId, componentId) => {
  const style=styleById(styleId);
  if(!style)return '';
  const component=String(componentId||'').replace(/^.*--/,'').replace(/^ui-/,'');
  const css=componentCSS[style.id]?.[component]||legacyComponentCSS[style.id]?.[component];
  const allBase=baseCSS(style),base=componentCSS[style.id]?.[component]?allBase:allBase.slice(0,allBase.indexOf('\n.ui-demo{'));
  const responsive=legacyResponsiveCSS(style.id,component);
  return (css ? `${base}\n${css}${responsive?`\n${responsive}`:''}${component==='drawer'?`\n${comparisonCSS}`:''}${component==='dialog'?`\n${legacyDialogComparisonCSS}`:''}` : baseCSS(style)) + `\n${inputFocusCSS}`;
};
